(132686, 6420, 843, '<td valign="top">Very creative. Great color &amp; detail.</td>', 'Very creative. Great color & detail.', '2002-10-03 17:07:00.000000', NULL, 1),
(132687, 6420, 2553, '<td valign="top">Sure wish you had flipped the shot so the kitty wasn''t upside down!  Very cool reflection though.  lhall-7</td>', 'Sure wish you had flipped the shot so the kitty wasn''t upside down!  Very cool reflection though.  lhall-7', '2002-10-03 19:46:00.000000', NULL, 1),
