(133033, 6453, 332, '<td valign="top">I like this one alot. Great job! -arnit</td>', 'I like this one alot. Great job! -arnit', '2002-10-04 21:14:00.000000', NULL, 1),
(133034, 6453, 3704, '<td valign="top">very beautiful photo, i like the reflection. Sharp focus, balanced saturation. overall perfect 10 waziz74</td>', 'very beautiful photo, i like the reflection. Sharp focus, balanced saturation. overall perfect 10 waziz74', '2002-10-04 21:53:00.000000', NULL, 1),
