(134134, 6552, 4246, '<td valign="top">a nicely focussed reflection but not a very interesting subject</td>', 'a nicely focussed reflection but not a very interesting subject', '2002-10-01 23:32:00.000000', NULL, 1),
(134135, 6552, 2716, '<td valign="top">Is that a Powershot G2 I see?</td>', 'Is that a Powershot G2 I see?', '2002-10-02 20:03:00.000000', NULL, 1),
(134136, 6552, 4378, '<td valign="top">X-cellent B&amp;W, excellent use of objects, resourcefulness. Could u teach the other participants what the challenge is about again?</td>', 'X-cellent B&W, excellent use of objects, resourcefulness. Could u teach the other participants what the challenge is about again?', '2002-10-03 12:20:00.000000', NULL, 1),
(134137, 6552, 1005, '<td valign="top">Cool balls, but the hand isn''t enough to fully "hide" your camera.  Shots works well in B&amp;W, but the glare of the sun is pretty potent.  Very good focus, nice framing.  Challenge aspects, close, but not quite the cigar!  6 Swash</td>', 'Cool balls, but the hand isn''t enough to fully "hide" your camera.  Shots works well in B&W, but the glare of the sun is pretty potent.  Very good focus, nice framing.  Challenge aspects, close, but not quite the cigar!  6 Swash', '2002-10-03 16:29:00.000000', NULL, 1),
(134138, 6552, 2989, '<td valign="top">The framing and reflection are rather odd, but it is a very creative reflection.  Good thing your camera isn''t reflecting too.</td>', 'The framing and reflection are rather odd, but it is a very creative reflection.  Good thing your camera isn''t reflecting too.', '2002-10-04 10:36:00.000000', NULL, 1),
(134139, 6552, 2158, '<td valign="top">The white corners detract from a very interesting picture.  The black and white really works well.</td>', 'The white corners detract from a very interesting picture.  The black and white really works well.', '2002-10-04 22:30:00.000000', NULL, 1),
(134140, 6552, 3072, '<td valign="top">I like your picture.</td>', 'I like your picture.', '2002-10-05 01:05:00.000000', NULL, 1),
