(134449, 6589, 4316, '<td valign="top">Perfect reflection!</td>', 'Perfect reflection!', '2002-10-01 13:31:00.000000', NULL, 1),
(134450, 6589, 4005, '<td valign="top">Why grey? I think, this motif would look better if it were colored!?! ...maybe I''m wrong! I like the idea with the continued arc! Greetings to Berlin! 7 KAOS</td>', 'Why grey? I think, this motif would look better if it were colored!?! ...maybe I''m wrong! I like the idea with the continued arc! Greetings to Berlin! 7 KAOS', '2002-10-01 18:08:00.000000', NULL, 1),
(134451, 6589, 1543, '<td valign="top">great, 8. queen</td>', 'great, 8. queen', '2002-10-01 21:15:00.000000', NULL, 1),
(134452, 6589, 2928, '<td valign="top">Superb This shot has a dramatic, futuristic but cold feel.  The lines in shot work to compliment the atmosphere really well Great shooting (10)</td>', 'Superb This shot has a dramatic, futuristic but cold feel.  The lines in shot work to compliment the atmosphere really well Great shooting (10)', '2002-10-02 11:52:00.000000', NULL, 1),
