(134719, 6608, 3786, '<td valign="top">Nice photo. I would like to seem the lipstick also in the reflection.</td>', 'Nice photo. I would like to seem the lipstick also in the reflection.', '2002-09-30 18:50:00.000000', NULL, 1),
(134720, 6608, 2158, '<td valign="top">I like the humour in this shot.</td>', 'I like the humour in this shot.', '2002-09-30 21:16:00.000000', NULL, 1),
(134721, 6608, 1280, '<td valign="top">Good image.  Grayce</td>', 'Good image.  Grayce', '2002-09-30 22:58:00.000000', NULL, 1),
(134722, 6608, 1779, '<td valign="top">don''t know why but i like this one. maybe it''s the simplisity or the girl or the lighting or the composition... but i like it. : ) LM</td>', 'don''t know why but i like this one. maybe it''s the simplisity or the girl or the lighting or the composition... but i like it. : ) LM', '2002-10-01 12:00:00.000000', NULL, 1),
