(134825, 6616, 4106, '<td valign="top">Ok, now youve gone and made me hungry</td>', 'Ok, now youve gone and made me hungry', '2002-10-01 11:06:00.000000', NULL, 1),
(134826, 6616, 2997, '<td valign="top">This is a very original shot. It would be great hanging in a local pizza restaurant.</td>', 'This is a very original shot. It would be great hanging in a local pizza restaurant.', '2002-10-01 11:09:00.000000', NULL, 1),
(134827, 6616, 4049, '<td valign="top">Too sharp</td>', 'Too sharp', '2002-10-01 13:02:00.000000', NULL, 1),
