(135509, 6663, 4098, '<td valign="top">I love vibrant colours.</td>', 'I love vibrant colours.', '2002-10-01 01:14:00.000000', NULL, 1),
(135510, 6663, 4008, '<td valign="top">A very pleasant scene with lovely color. Not so strong on the reflection subject.</td>', 'A very pleasant scene with lovely color. Not so strong on the reflection subject.', '2002-10-01 03:40:00.000000', NULL, 1),
